-- Global onboarding thread + note content reconcile (affects all users).
-- Threads are authored by the system Plot twist instance and routed via the
-- @plot.updates auto-maintained announce topic (the @plot.updates topic is how
-- every user receives them — file_thread_priority_for_topic_members files them).
DO $$
DECLARE
    c_system_instance_id CONSTANT uuid := '0199b6f4-ae64-7718-0000-000000000001';
    c_twist_package_id CONSTANT uuid := '0199b6f4-ae64-7718-8a02-44716f30358f';
