    SELECT id INTO v_plot_twist_id FROM public.twist
        WHERE twist_package_id = c_twist_package_id AND environment = 'public' LIMIT 1;
    SELECT id INTO v_updates_topic_id FROM public.topic
        WHERE key = '@plot.updates' AND auto_maintained = TRUE AND team_id IS NULL LIMIT 1;
    -- Atlas-robust: skip on fresh DBs where the system twist / topic isn't seeded yet.
    IF v_plot_twist_id IS NULL OR v_updates_topic_id IS NULL THEN RETURN; END IF;

